import type { DistrictId } from './maharashtraGeo.generated';

export type DioStatus = 'Active' | 'Standby' | 'Field Operation';

export interface DioRecord {
  officer: string;
  status: DioStatus;
}

/**
 * Operational data for each District Information Office.
 *
 * This is the only file you need to edit when DIO data changes. Geography lives in
 * maharashtraGeo.generated.ts and is regenerated by `npm run build:geo`.
 *
 * The first version of this map only had 8 coverage zones, several of which span more than
 * one district (e.g. "Thane & Palghar"). Those zones are carried over below unchanged, so every
 * district in a zone shows that zone's officer and status. As soon as you have per-district
 * data, split the entry: one object per district.
 *
 * Districts with no entry are shown as "Not configured" rather than guessed at.
 */
const DIO_ZONES: ReadonlyArray<{ districtIds: DistrictId[] } & DioRecord> = [
  { districtIds: ['mumbai-city', 'mumbai-suburban'], officer: 'Amit Desai (HQ)', status: 'Active' },
  { districtIds: ['thane', 'palghar'], officer: 'Pooja Sawant', status: 'Active' },
  { districtIds: ['pune'], officer: 'Suresh Patil', status: 'Active' },
  { districtIds: ['nashik'], officer: 'Ramesh Kulkarni', status: 'Standby' },
  { districtIds: ['chhatrapati-sambhajinagar'], officer: 'Kailash Jadhav', status: 'Field Operation' },
  { districtIds: ['nagpur', 'wardha'], officer: 'Vinod Meshram', status: 'Active' },
  { districtIds: ['kolhapur', 'sangli', 'satara'], officer: 'Anand Shinde', status: 'Active' },
  { districtIds: ['amravati', 'akola'], officer: 'Sunil Deshmukh', status: 'Standby' },
];

export const DIO_BY_DISTRICT: Partial<Record<DistrictId, DioRecord>> = Object.fromEntries(
  DIO_ZONES.flatMap(({ districtIds, officer, status }) =>
    districtIds.map((id) => [id, { officer, status }] as const)
  )
);
